    /// <summary>
    /// 所有Headstage的当前的状态
    /// Key是HeadstageData的DeviceName
    /// </summary>
    public static Dictionary<string, HeadstageState> HeadstageState { get; set; } = new();

    /// <summary>
    /// 当前查看哪个阻抗通道
    /// </summary>
    public static uint ImpedanceChannelIndex { get; set; } = 0;

    /// <summary>
    /// 带通滤波
    /// </summary>
    /// <param name="voltageArray"></param>
    /// <param name="coefficient"></param>
    /// <returns></returns>
    public static float[] FirFilt(int[] voltageArray, float[] coefficient)
    {
        var result = new float[voltageArray.Length];
        for (int i = 0; i < result.Length; i++)
        {
            float y = 0;
            for (int j = 0; j < coefficient.Length; j++)
            {
                if (j > i)
                {
                    break;
                }
                y += coefficient[j] * voltageArray[i - j];
            }
            result[i] = y;
        }
        return result;
    }

    /// <summary>
    /// 跳过一些点
    /// </summary>
    /// <param name="filterdArray"></param>
    /// <returns></returns>
    public static float[] SkipPoints(float[] filterdArray)
    {
        var result = new float[filterdArray.Length - ImpedanceBufferSkipPoints];
        for (int i = ImpedanceBufferSkipPoints; i < filterdArray.Length; i++)
        {
            result[i - ImpedanceBufferSkipPoints] = filterdArray[i];
        }
        return result;
    }

    /// <summary>
    /// 找一个窗内的峰峰值
    /// </summary>
    /// <param name="array"></param>
    /// <param name="startIndex"></param>
    /// <param name="length"></param>
    /// <returns></returns>
    public static float FindPeakToPeak(float[] array, int startIndex, int length)
    {
        float maxValue = float.NegativeInfinity;
        int maxValueIndex = -1;
        for (int i = 0; i < length; i++)
        {
            var currentValue = array[startIndex + i];
            if (currentValue > maxValue)
            {
                maxValue = currentValue;
                maxValueIndex = i;
            }
        }
        float minValue = float.PositiveInfinity;
        //从该最大值后找最小值(不包括该最大值)
        if (maxValueIndex < MinValueBufferRange)
        {
            for (int i = 0; i < MinValueBufferRange; i++)
            {
                var currentValue = array[maxValueIndex + i + 1];
                if (currentValue < minValue)
                {
                    minValue = currentValue;
                }
            }
        }
        //从该最大值前找最小值(不包括该最大值)
        else
        {
            for (int i = 0; i < MinValueBufferRange; i++)
            {
                var currentValue = array[maxValueIndex - i - 1];
                if (currentValue < minValue)
                {
                    minValue = currentValue;
                }
            }
        }
        return maxValue - minValue;
    }

    /// <summary>
    /// 参考W3-SDK阻抗计算方法:
    /// 计算平均电压，单位uV
    /// 滑窗计算，窗长16，
    /// 每个窗里找出16个点里最大数Max，
    /// 如果最大数的位置出现在滑窗16个点里前4个点，取该点往后的4个点，否则取该点往前的4个点(都不包括该点)
    /// 算出这4个点的最小值Min，每个窗算一个峰峰值为Max-Min。
    /// 将每个窗的峰峰值汇总再算一次平均后得出的平均电压
    /// </summary>
    /// <param name="restArray"></param>
    /// <returns></returns>
    public static float MeanVoltage(float[] restArray)
    {
        float peakToPeakSum = 0;
        float peakToPeakCount = 0;
        //去掉最后多余不够一个窗的点
        var remainder = restArray.Length % WindowLength;
        for (int i = 0; i < restArray.Length - remainder; i += WindowLength)
        {
            var peakToPeak = FindPeakToPeak(restArray, i, WindowLength);
            peakToPeakSum += peakToPeak;
            peakToPeakCount += 1;
        }
        return peakToPeakSum / peakToPeakCount;
    }

    /// <summary>
    /// 计算阻抗的过程,单位Ω
    /// </summary>
    /// <param name="voltageArray"></param>
    /// <returns></returns>
    public static float ComputeImpedance(float[] voltageArray)
    {
        var restArray = SkipPoints(voltageArray);
        var meanVoltage = MeanVoltage(restArray);
        var impedanceValue = meanVoltage / ExcitationCurrent * 1000 * 1000;
        //根据拟合的结果进行计算
        if (impedanceValue < 9000000)
        {
            impedanceValue = 0.0033f * impedanceValue - 1374.5f;
        }
        else if (impedanceValue < 15000000)
        {
            impedanceValue = 0.0081f * impedanceValue - 45938f;
        }
        else
        {
            impedanceValue = 0.0132f * impedanceValue - 121480f;
        }
        if (impedanceValue < 0)
        {
            impedanceValue = 0;
        }
        return impedanceValue;
    }
}

/// <summary>
/// Headstage当前处于什么状态
/// </summary>
public enum HeadstageState
{
    /// <summary>
    /// 采集模式
    /// </summary>
    Data,

    /// <summary>
    /// 阻抗模式
    /// </summary>
    Impedance
}
